export function keyOf(date){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;}
export function shiftDate(key,offset){const date=new Date(key+'T12:00:00');date.setDate(date.getDate()+offset);return keyOf(date);}
export function dayTotal(day){return day.items.reduce((sum,item)=>sum+item.calories,0);}
export function validateData(input){if(!input||!Number.isInteger(input.goal)||input.goal<1||input.goal>100000||!input.days||typeof input.days!=='object'||Array.isArray(input.days))throw Error('Invalid backup');const days={};for(const [date,day] of Object.entries(input.days)){if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||keyOf(new Date(date+'T12:00:00'))!==date||!day||!Array.isArray(day.items)||typeof day.note!=='string'||day.note.length>5000)throw Error('Invalid day');const ids=new Set();const items=day.items.map(item=>{if(!item||typeof item.id!=='string'||!item.id||ids.has(item.id)||!['breakfast','lunch','dinner','snack'].includes(item.meal)||typeof item.name!=='string'||!item.name.trim()||item.name.length>100||!Number.isInteger(item.calories)||item.calories<0||item.calories>100000)throw Error('Invalid food');ids.add(item.id);return {id:item.id,meal:item.meal,name:item.name,calories:item.calories};});days[date]={items,note:day.note};}return {goal:input.goal,days};}
